package com.oms.supplychain;

import com.oms.supplychain.service.wms.*;
import com.oms.supplychain.service.warehouse.impl.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
import static com.oms.supplychain.PurchaseWorkspaceTest.m;

public class PurchaseCutoffTest {
    static AnnotationConfigApplicationContext ctx;static JdbcTemplate db;static PurchaseWorkspaceService service;static PurchaseCutoffService cutoff;static InboundReceiptReviewService reviews;
    java.util.concurrent.CountDownLatch createEntered,createRelease;
    PurchaseWorkspaceTest fixture=new PurchaseWorkspaceTest();com.sun.net.httpserver.HttpServer server;AtomicInteger cancels=new AtomicInteger(),queries=new AtomicInteger(),creates=new AtomicInteger();String cancelReply="<response><flag>success</flag><status>CANCELED</status></response>",queryReply=cancelReply;
    @BeforeAll static void open(){ctx=new AnnotationConfigApplicationContext(PurchaseWorkspaceTest.Config.class);db=ctx.getBean(JdbcTemplate.class);service=ctx.getBean(PurchaseWorkspaceService.class);cutoff=ctx.getBean(PurchaseCutoffService.class);reviews=ctx.getBean(InboundReceiptReviewService.class);PurchaseWorkspaceTest.context=ctx;PurchaseWorkspaceTest.db=db;PurchaseWorkspaceTest.service=service;PurchaseWorkspaceTest.warehouses=ctx.getBean(WarehouseWorkspaceService.class);org.springframework.test.util.ReflectionTestUtils.setField(ctx.getBean(WmsConnections.class),"encryptionKey",java.util.Base64.getEncoder().encodeToString(new byte[32]));}
    @AfterAll static void close(){ctx.close();}
    @BeforeEach void seed(){fixture.seed();}
    @AfterEach void stop(){if(server!=null)server.stop(0);}
    WmsInboundService inbound(){return ctx.getBean(WmsInboundService.class);}
    long receiptId(long ticket){return ((Number)inbound().task("QM",ticket).get("receipt_id")).longValue();}
    long po(){return db.queryForObject("SELECT id FROM po_info",Long.class);}
    long request(String kind,long key,String mode){Map<String,Object> d=service.detail("QM",kind,key);return ((Number)cutoff.request("QM",kind,key,m("mode",mode,"reason","验收截单","cutoff_version",d.get("cutoffVersion")),"tester").get("id")).longValue();}
    Map<String,Object> operation(long op){return db.queryForMap("SELECT * FROM purchase_cutoff WHERE id=?",op);}
    Map<String,Object> receipt(long id){return service.detail("QM","receipt",id);}
    long remaining(long po){Map<String,Object> l=service.purchaseLines("QM",(String)service.detail("QM","purchase",po).get("poSn")).get(0);return ((Number)l.get("quantity")).longValue()-((Number)l.get("scheduledQuantity")).longValue();}
    long real(int qty,boolean partial) throws Exception {
        server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.createContext("/router",x->{String q=x.getRequestURI().getRawQuery();String response;if(q.contains("order.cancel")){cancels.incrementAndGet();response=cancelReply;}else if(q.contains("entryorder.query")){queries.incrementAndGet();response=queryReply;}else{creates.incrementAndGet();if(createEntered!=null){createEntered.countDown();try{createRelease.await(10,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}response="<response><flag>success</flag><entryOrderId>EXT-ORDER</entryOrderId></response>";}x.getRequestBody().close();byte[] b=response.getBytes(java.nio.charset.StandardCharsets.UTF_8);x.sendResponseHeaders(200,b.length);try(java.io.OutputStream o=x.getResponseBody()){o.write(b);}});server.start();long connection=fixture.realVirtual("QIMEN","http://127.0.0.1:"+server.getAddress().getPort()+"/router");db.update("UPDATE wms_connection SET partial_inbound_cancel=? WHERE id=?",partial?1:0,connection);long po=fixture.purchase(fixture.line("A",qty,"2.50"));service.approve("QM",po,"tester");long ticket=service.approveReceipt("QM",fixture.receipt(po,qty),"tester");fixture.accepted(ticket);return ticket;
    }
    void receive(long t,int qty,String msg,boolean finalReceipt){inbound().accept("QM",inbound().task("QM",t),fixture.confirmation(t,msg,qty,0,finalReceipt));}
    Map<String,Object> manual(long item,long ticket){Map<String,Object> d=service.detail("QM","ticket",ticket);List<Map<String,Object>> lines=new ArrayList<>();for(Object v:(List<?>)d.get("lines")){Map<?,?> g=(Map<?,?>)v;lines.add(m("id",g.get("id"),"good",g.get("numberZp"),"bad",g.get("numberCp")));}return m("confirmed_stopped",true,"external_order","EXT-ORDER","evidence","已联系仓库，确认本批停止收货并核对全部实收","lines",lines);}
    long item(long op){return db.queryForObject("SELECT id FROM purchase_cutoff_item WHERE cutoff_id=?",Long.class,op);}
    @Test void unapprovedReceiptWithdrawsLocallyWithoutFakeWarehouseLogAndCanBeReplaced(){long p=fixture.purchase(fixture.line("A",100,"2.50"));service.approve("QM",p,"tester");long n=fixture.receipt(p,30),op=request("receipt",n,"WITHDRAW");assertEquals(70,remaining(p));assertTrue(fixture.receipt(p,20)>0);cutoff.process("QM",op);assertEquals("COMPLETED",operation(op).get("state"));assertEquals(6,receipt(n).get("noState"));assertEquals(30L,receipt(n).get("cancelledQuantity"));assertEquals(80,remaining(p));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM wms_interaction_log",Integer.class));assertThrows(IllegalArgumentException.class,()->service.approveReceipt("QM",n,"tester"));}
    @Test void pendingRealTaskCancellationBlocksDelayedCreate(){long t=fixture.realTicket(10),n=receiptId(t),op=request("receipt",n,"WITHDRAW");Map<String,Object> task=inbound().task("QM",t);inbound().dispatch("QM",((Number)task.get("id")).longValue());assertEquals("PENDING",inbound().task("QM",t).get("dispatch_state"));cutoff.process("QM",op);inbound().dispatch("QM",((Number)task.get("id")).longValue());assertEquals("CANCELED",inbound().task("QM",t).get("dispatch_state"));assertEquals(6,receipt(n).get("noState"));assertEquals(10,remaining(po()));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM wms_interaction_log",Integer.class));}
    @Test void warehouseConfirmationWaitsForSuccessfulPostingBeforeReleasingBooking() throws Exception {long t=real(10,true);receive(t,4,"PART",false);long n=receiptId(t),op=request("receipt",n,"WITHDRAW");PurchaseWorkspaceTest.fail.add("A");cutoff.process("QM",op);assertEquals("CONFIRMED",inbound().task("QM",t).get("cancel_state"));assertEquals(0,remaining(po()));assertEquals(3,receipt(n).get("noState"));assertEquals("POSTING_PENDING",db.queryForObject("SELECT state FROM purchase_cutoff_item WHERE cutoff_id=?",String.class,op));PurchaseWorkspaceTest.fail.clear();cutoff.process("QM",op);assertEquals(5,receipt(n).get("noState"));assertEquals(6,remaining(po()));assertEquals(6L,receipt(n).get("cancelledQuantity"));assertEquals(1,cancels.get());int calls=PurchaseWorkspaceTest.calls.get();cutoff.process("QM",op);assertEquals(calls,PurchaseWorkspaceTest.calls.get());}
    @Test void unverifiedPartialWarehouseRequiresExplicitManualConfirmation() throws Exception {long t=real(10,false);receive(t,4,"PART",false);inbound().post("QM",t);long n=receiptId(t),op=request("receipt",n,"WITHDRAW");cutoff.process("QM",op);assertEquals("WAIT_REVIEW",operation(op).get("state"));assertEquals(0,cancels.get());assertEquals(0,remaining(po()));Map<String,Object> bad=manual(item(op),t);((Map<String,Object>)((List<?>)bad.get("lines")).get(0)).put("good",5);assertThrows(IllegalArgumentException.class,()->cutoff.confirmWarehouse("QM",item(op),bad,"auditor"));cutoff.confirmWarehouse("QM",item(op),manual(item(op),t),"auditor");cutoff.process("QM",op);assertEquals(5,receipt(n).get("noState"));assertEquals(6,remaining(po()));assertEquals("CLOSED",service.detail("QM","ticket",t).get("progress"));}
    @Test void successfulCancelRequestIsNotCancellationProofAndReceiptsDoNotEraseIntent() throws Exception {cancelReply="<response><flag>success</flag></response>";long t=real(10,true),n=receiptId(t),op=request("receipt",n,"WITHDRAW");cutoff.process("QM",op);assertEquals("PENDING",inbound().task("QM",t).get("cancel_state"));assertEquals(0,remaining(po()));receive(t,3,"WHILE_CANCELING",false);assertEquals("PENDING",inbound().task("QM",t).get("cancel_state"));cutoff.process("QM",op);assertEquals("COMPLETED",operation(op).get("state"));assertEquals(5,receipt(n).get("noState"));assertEquals(7,remaining(po()));assertEquals(1,cancels.get());assertEquals(1,queries.get());}
    @Test void unknownCancelOnlyQueriesOriginalTaskOnRetry() throws Exception {cancelReply="<malformed>";long t=real(10,true),op=request("receipt",receiptId(t),"WITHDRAW");cutoff.process("QM",op);assertEquals("UNKNOWN",inbound().task("QM",t).get("cancel_state"));assertEquals(0,remaining(po()));cutoff.process("QM",op);assertEquals("COMPLETED",operation(op).get("state"));assertEquals(1,cancels.get());assertEquals(1,queries.get());}
    @Test void explicitWarehouseRefusalKeepsBookingUntilOperatorRetries() throws Exception {cancelReply="<response><flag>failure</flag><message>仓库作业中</message></response>";long t=real(10,true),n=receiptId(t),op=request("receipt",n,"WITHDRAW");cutoff.process("QM",op);assertEquals("WAIT_REVIEW",operation(op).get("state"));assertEquals(0,remaining(po()));assertEquals("REJECTED",inbound().task("QM",t).get("cancel_state"));cancelReply="<response><flag>success</flag><status>CANCELED</status></response>";cutoff.retry("QM","receipt",n,((Number)receipt(n).get("cutoffVersion")).longValue(),"tester");cutoff.process("QM",op);assertEquals("COMPLETED",operation(op).get("state"));assertEquals(2,cancels.get());}
    @Test void wholePurchaseTerminationBlocksNewArrivalsButKeepsOriginalPlan(){long p=fixture.purchase(fixture.line("A",100,"2.50"));service.approve("QM",p,"tester");long n=fixture.receipt(p,30);long op=request("purchase",p,"TERMINATE");assertThrows(IllegalArgumentException.class,()->fixture.receipt(p,20));cutoff.process("QM",op);assertEquals(5,service.detail("QM","purchase",p).get("poState"));assertEquals(100,service.detail("QM","purchase",p).get("numberExpected"));assertEquals(6,receipt(n).get("noState"));assertThrows(IllegalArgumentException.class,()->fixture.receipt(p,20));}
    @Test void cancelledReceiptNewFactIsRetainedAndRejectingItDoesNotPostInventory(){long t=fixture.realTicket(10),n=receiptId(t),op=request("receipt",n,"WITHDRAW");cutoff.process("QM",op);assertThrows(IllegalArgumentException.class,()->receive(t,2,"LATE",true));long review=db.queryForObject("SELECT id FROM wms_inbound_receipt_review",Long.class);assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM wms_receipt_line",Integer.class));reviews.decide("QM",review,m("decision","REJECT","reason","已向仓库核实是错误回传","control_version",0),"auditor");assertEquals(10,remaining(po()));assertEquals(0,PurchaseWorkspaceTest.calls.get());assertThrows(IllegalArgumentException.class,()->receive(t,2,"LATE",true));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM wms_inbound_receipt_review",Integer.class));}
    @Test void manualLateFactPostsOnceAndConsumesOnlyItsActualQuantity(){long t=fixture.realTicket(10),n=receiptId(t),op=request("receipt",n,"WITHDRAW");cutoff.process("QM",op);assertThrows(IllegalArgumentException.class,()->receive(t,2,"LATE",true));long r=db.queryForObject("SELECT id FROM wms_inbound_receipt_review",Long.class);reviews.decide("QM",r,m("decision","ACCEPT","reason","已核实截停前实际收货2件","control_version",0,"confirmed_actual",true),"auditor");assertEquals(8,remaining(po()));assertTrue(inbound().post("QM",t));assertEquals(5,receipt(n).get("noState"));assertEquals(2,((Number)receipt(n).get("numberActually")).intValue());assertEquals(8L,receipt(n).get("cancelledQuantity"));int calls=PurchaseWorkspaceTest.calls.get();receive(t,2,"LATE",true);inbound().post("QM",t);assertEquals(calls,PurchaseWorkspaceTest.calls.get());}
    @Test void lateFactCannotStealCapacityAlreadyReassignedToAnotherArrival(){long t=fixture.realTicket(10),n=receiptId(t),op=request("receipt",n,"WITHDRAW");cutoff.process("QM",op);fixture.receipt(po(),10);assertThrows(IllegalArgumentException.class,()->receive(t,2,"LATE",true));long r=db.queryForObject("SELECT id FROM wms_inbound_receipt_review",Long.class);assertThrows(IllegalArgumentException.class,()->reviews.decide("QM",r,m("decision","ACCEPT","reason","核对实收","control_version",0,"confirmed_actual",true),"auditor"));assertEquals("WAIT_REVIEW",reviews.detail("QM",r).get("state"));assertEquals(0,PurchaseWorkspaceTest.calls.get());assertEquals(0,remaining(po()));}
    @Test void staleCrossCompanyAndOverlappingCommandsDoNotCreateAnotherIntent(){long p=fixture.purchase(fixture.line("A",10,"2.50"));service.approve("QM",p,"tester");long n=fixture.receipt(p,10);request("receipt",n,"WITHDRAW");assertThrows(IllegalArgumentException.class,()->cutoff.request("QM","receipt",n,m("reason","重复","cutoff_version",0),"tester"));assertThrows(IllegalArgumentException.class,()->cutoff.request("OTHER","receipt",n,m("reason","跨公司","cutoff_version",0),"tester"));assertThrows(IllegalArgumentException.class,()->request("purchase",p,"TERMINATE"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM purchase_cutoff",Integer.class));}
    @Test void createAlreadyInFlightMustFinishBeforeWarehouseCancellation() throws Exception {long t=real(10,true);db.update("UPDATE wms_inbound_task SET dispatch_state='PENDING',attempts=0 WHERE ticket_id=?",t);long task=((Number)inbound().task("QM",t).get("id")).longValue();createEntered=new java.util.concurrent.CountDownLatch(1);createRelease=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newSingleThreadExecutor();try{java.util.concurrent.Future<?> sent=pool.submit(()->inbound().dispatch("QM",task));assertTrue(createEntered.await(5,java.util.concurrent.TimeUnit.SECONDS));long op=request("receipt",receiptId(t),"WITHDRAW");cutoff.process("QM",op);assertEquals(0,cancels.get());assertEquals(0,remaining(po()));createRelease.countDown();sent.get(10,java.util.concurrent.TimeUnit.SECONDS);cutoff.process("QM",op);assertEquals("COMPLETED",operation(op).get("state"));assertEquals(1,creates.get());assertEquals(1,cancels.get());assertEquals(10,remaining(po()));}finally{createRelease.countDown();pool.shutdownNow();}}
    @Test void bookingReleaseAndNewArrivalAreSerializedOnThePurchase() throws Exception {long t=fixture.realTicket(10),p=po(),op=request("receipt",receiptId(t),"WITHDRAW");java.util.concurrent.ExecutorService pool=java.util.concurrent.Executors.newFixedThreadPool(2);java.util.concurrent.CountDownLatch gate=new java.util.concurrent.CountDownLatch(1);try{java.util.concurrent.Future<?> done=pool.submit(()->{try{gate.await();cutoff.process("QM",op);}catch(InterruptedException e){throw new RuntimeException(e);}});java.util.concurrent.Future<Boolean> newReceipt=pool.submit(()->{gate.await();try{fixture.receipt(p,10);return true;}catch(IllegalArgumentException e){return false;}});gate.countDown();done.get(10,java.util.concurrent.TimeUnit.SECONDS);boolean created=newReceipt.get(10,java.util.concurrent.TimeUnit.SECONDS);assertEquals(created?0:10,remaining(p));assertEquals("COMPLETED",operation(op).get("state"));assertEquals(0,PurchaseWorkspaceTest.calls.get());}finally{pool.shutdownNow();}}

    @Test void lateFactBeforeBookingReleaseUsesOriginalHeldCapacity() throws Exception {long t=real(10,true);receive(t,4,"PART",false);long n=receiptId(t),op=request("receipt",n,"WITHDRAW");PurchaseWorkspaceTest.fail.add("A");cutoff.process("QM",op);assertEquals("CONFIRMED",inbound().task("QM",t).get("cancel_state"));assertEquals(0,remaining(po()));assertThrows(IllegalArgumentException.class,()->receive(t,2,"LATE_HELD",true));long review=db.queryForObject("SELECT id FROM wms_inbound_receipt_review",Long.class);reviews.decide("QM",review,m("decision","ACCEPT","reason","已核实原批次截停前另收2件","control_version",0,"confirmed_actual",true),"auditor");assertEquals(0,remaining(po()));PurchaseWorkspaceTest.fail.clear();cutoff.process("QM",op);assertEquals("COMPLETED",operation(op).get("state"));assertEquals(4,remaining(po()));assertEquals(6,((Number)receipt(n).get("numberActually")).intValue());assertEquals(4L,receipt(n).get("cancelledQuantity"));}

    @Test void finalShortReceiptDuringCutoffEndsBatchWithoutSendingAnotherCancel() throws Exception {long t=real(10,false),n=receiptId(t),op=request("receipt",n,"WITHDRAW");receive(t,4,"FINAL",true);inbound().post("QM",t);assertEquals(0,remaining(po()));cutoff.process("QM",op);assertEquals("COMPLETED",operation(op).get("state"));assertEquals(5,receipt(n).get("noState"));assertEquals(6,remaining(po()));assertEquals(0,cancels.get());assertEquals("FINAL_RECEIPT",db.queryForObject("SELECT warehouse_state FROM purchase_cutoff_item WHERE cutoff_id=?",String.class,op));assertThrows(IllegalArgumentException.class,()->receive(t,1,"LATE_FINAL",true));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM wms_inbound_receipt_review WHERE state='WAIT_REVIEW'",Integer.class));}

}
